import{_ as s,o as i,c as e,a4 as t}from"./chunks/framework.DzJZdBQK.js";const k=JSON.parse('{"title":"一次Jfinal使用ehcache的错误记录","description":"","frontmatter":{"date":"2020-03-07T11:11:38","title":"一次Jfinal使用ehcache的错误记录","categories":["jfinal","ehcache"],"tags":["jfinal","ehcache"]},"headers":[{"level":2,"title":"问题","slug":"问题","link":"#问题","children":[]},{"level":2,"title":"解决","slug":"解决","link":"#解决","children":[{"level":3,"title":"更好的方式","slug":"更好的方式","link":"#更好的方式","children":[]}]}],"relativePath":"posts/java/ehcache.md","filePath":"posts/java/ehcache.md"}'),h={name:"posts/java/ehcache.md"};function l(n,a,p,c,d,o){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Jfinal已经集成了EhCache缓存，只要简单配置就可以使用EhCache。最近的一个字典表数据量比较大，于是开启了EhCache，页面加载速度明显变快。昨日服务突然无法正常启动，错误如下（非法完整错误日志）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">net.sf.ehcache.CacheException:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> java.io.InvalidClassException:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.xxx.model.Concept</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> class incompatible: stream classdesc serialVersionUID = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-1234</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, local class serialVersionUID = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-5678</span></span></code></pre></div><p>看提示我们知道是serialVersionUID版本引起的问题。我们知道ehcache就会进行存盘的，如果保存的对象版本不一致就有可能出现这个问题，此时回忆起对<code>Concept</code>所在的表做了修改和重新生成。</p><h2 id="解决" tabindex="-1">解决 <a class="header-anchor" href="#解决" aria-label="Permalink to &quot;解决&quot;">​</a></h2><p>问题基本清晰了，那解决方法其实是相对简单的，把缓存的文件删除就可以了。</p><p>具体做法是这样的，找到<code>ehcache.xml</code>配置文件的的存盘位置，这里我用了<code>java.io.tmpdir</code>，不同操作系统类型此路径可能不一致，可以在程序中打印出来看下， 我这里是<code>/var/folders/d0/..</code>。</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">System.out.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">println</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(System.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getProperty</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;java.io.tmpdir&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span></code></pre></div><p>删除临时文件，需要根据自己的实际路径进行删除。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/folders</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> d0</span></span></code></pre></div><p>重新启动服务，正常启动。</p><h3 id="更好的方式" tabindex="-1">更好的方式 <a class="header-anchor" href="#更好的方式" aria-label="Permalink to &quot;更好的方式&quot;">​</a></h3><p>因为系统是可以正常使用的，可以编写个清理的接口，这样可以在数据结构调整时及时清理缓存。</p>`,13)])])}const g=s(h,[["render",l]]);export{k as __pageData,g as default};
